package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenQuantityFractionScopeTest {
 private static Question question(String a,String au,String b,String bu){Question q=new Question(QuantityAsFraction.ID,"두 수량은 "+a+" "+au+"와 "+b+" "+bu+"입니다.\n첫 번째 수량을 두 번째 수량의 분수로 나타내세요.","poison","999");q.answerFormat="fraction";q.stepSupport=false;return q;}
 @Test public void normalSevenMixesBothTimeDirectionsAndLegacyWithoutChangingSix(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(QuantityAsFraction.ID,7));var seven=GlobalCurriculum.limits(pack.id,QuantityAsFraction.ID,7);var six=GlobalCurriculum.limits(pack.id,QuantityAsFraction.ID,6);assertTrue(seven.quantityUnitConversions());assertFalse(six.quantityUnitConversions());Generator g=new Generator(new Random(355));List<String>recent=new ArrayList<>();Set<String>families=new HashSet<>();
  for(int i=0;i<150;i++){Question q=g.next(QuantityAsFraction.ID,recent,false,seven);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=QuantityAsFraction.read(q);assertNotNull(v);assertTrue(seven.allows(q));families.add(v.legacy()?"same":v.firstUnit());assertTrue(new Checker().check(q,List.of(),List.of(v.value().n+"/"+v.value().d)).correct());assertEquals(v.legacy()?5:7,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}
  assertEquals(Set.of("same","min","hour"),families);for(int i=0;i<100;i++){Question q=g.next(QuantityAsFraction.ID,List.of(),false,six);var v=QuantityAsFraction.read(q);assertTrue(v.legacy());assertTrue(Set.of("kg","m","L").contains(v.firstUnit()));assertTrue(v.first().compareTo(Rational.of(100))<=0);assertTrue(v.second().compareTo(Rational.of(100))<=0);}
  assertFalse(GlobalCurriculum.available(new Learning.Profile()).stream().anyMatch(s->s.id.equals(QuantityAsFraction.ID)));
 }
 @Test public void officialTimeOrderAndGeneralPublicQuantitiesIgnorePrivateAuthority(){
  String[][]cases={{"20","min","1","hour","1/3"},{"1","hour","20","min","3/1"},{"5","kg","25","kg","1/5"},{"500","kg","2500","kg","1/5"},{"0","min","1","hour","0/1"},{"60","min","1","hour","1/1"},{"120","min","1","hour","2/1"},{"1.5","kg","500","g","3/1"},{"0.2","L","0.6","L","1/3"},{"20","s","1","min","1/3"},{"1","km","250","m","4/1"},{"1000","mg","1","g","1/1"}};
  for(String[]c:cases){Question q=question(c[0],c[1],c[2],c[3]);StudyGuide poisoned=new StudyGuide().step("private","private","","999");q.studyGuide=poisoned;String prompt=q.prompt;var v=QuantityAsFraction.read(q);assertNotNull(prompt,v);assertEquals(Expression.number(c[4]),v.value());assertTrue(new Checker().check(q,List.of(),List.of(c[4])).correct());HelpPlan h=HelpPlan.forQuestion(q);StudyGuide visible=QuantityAsFraction.guide(q);assertEquals(v.legacy()?5:7,h.size());assertFalse(h.canTransfer());for(int i=0;i<h.size();i++){assertTrue(h.step(i).accepts(visible.frames.get(i).expected));assertEquals("",h.step(i).after);assertTrue(h.step(i).options.isEmpty());}assertSame(poisoned,q.studyGuide);assertEquals("999",q.studyGuide.frames.get(0).expected);assertEquals(prompt,q.prompt);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);}
  var time=QuantityAsFraction.read(question("20","min","1","hour"));assertEquals(Rational.ONE,time.firstMultiplier());assertEquals(Rational.of(60),time.secondMultiplier());assertEquals("min",time.commonUnit());assertEquals("20",time.firstCount().toString());assertEquals("60",time.secondCount().toString());var decimal=QuantityAsFraction.read(question("0.2","L","0.6","L"));assertEquals("5",decimal.quantization().toString());assertEquals("1",decimal.firstCount().toString());assertEquals("3",decimal.secondCount().toString());
 }
 @Test public void fiveStepDraftAndNewSevenBlankPublicHelpRetainManualInputs(){
  Question legacy=QuantityAsFraction.make(5,25,"kg");HelpPlan old=HelpPlan.forQuestion(legacy);List<String>values=List.of("5","25","5","1","5");List<String>before=List.of("첫 번째 수량 a = ","두 번째 수량 b = ","최대공약수 g = gcd(a, b) = ","분자 n = a ÷ g = ","분모 d = b ÷ g = ");for(int i=0;i<5;i++){assertEquals(before.get(i),old.step(i).before);assertTrue(old.step(i).accepts(values.get(i)));}HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=legacy.id;d.teachingVersion="quantity-as-fraction-v1";d.stage=5;d.entries=new ArrayList<>(values);var restored=old.restore(d.copy(),legacy.id);assertEquals(5,restored.stage);assertEquals(values,restored.entries.subList(0,5));
  assertEquals("1/5",old.enteredAnswer(restored));Question time=question("20","min","1","hour");var seven=HelpPlan.forQuestion(time);assertEquals("quantity-as-fraction-conversion-v1",seven.restore(null,time.id).teachingVersion);List<String>expected=List.of("20","1","20","60","20","1","3");for(int i=0;i<7;i++)assertTrue(seven.step(i).accepts(expected.get(i)));HelpPlan.Draft done=seven.restore(null,time.id);done.stage=7;done.entries=new ArrayList<>(expected);assertEquals("1/3",seven.enteredAnswer(done));assertEquals(1,FractionInput.errorPart(time,"2/3"));assertEquals(2,FractionInput.errorPart(time,"1/4"));assertEquals(0,FractionInput.errorPart(time,"20/60"));assertFalse(new Checker().check(time,List.of(),List.of("0.333")).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(time,List.of(),List.of("")).status);
 }
 @Test public void incompatibleOrInvalidPublicQuantitiesCannotUseSavedHelp(){
  for(String[]c:new String[][]{{"1","kg","2","m"},{"1","unknown","2","kg"},{"-1","kg","2","kg"},{"1","kg","0","kg"},{"1e2","kg","2","kg"},{"0.0000000000001","kg","1","kg"},{"1".repeat(31),"kg","2","kg"}}){Question q=question(c[0],c[1],c[2],c[3]);q.studyGuide=new StudyGuide().step("private","private","","999");assertNull(QuantityAsFraction.read(q));assertNull(HelpPlan.forQuestion(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("999")).status);}
  assertNull(QuantityAsFraction.read(null));assertNull(QuantityAsFraction.guide(null));assertEquals(0,QuantityAsFraction.errorPart(null,"1/2"));assertEquals(Checker.Status.INPUT_NEEDED,QuantityAsFraction.check(null,List.of("1/2")).status);try{new CurriculumLimits("quantityUnitConversions=maybe");fail();}catch(IllegalArgumentException expected){}
 }
 @Test public void selectedFamilyExhaustionUsesGlobalFreshThenOldest(){
  CurriculumLimits limits=new CurriculumLimits("quantityUnitConversions=true;minGiven=1;maxGiven=1");Map<String,Integer>recent=new HashMap<>();Random pinned=new Random(){@Override public boolean nextBoolean(){return false;}@Override public int nextInt(int bound){return 0;}};String oldest=null;
  for(int i=0;i<5;i++){Question q=QuantityAsFraction.next(pinned,limits,recent);assertTrue(limits.allows(q));assertFalse(recent.containsKey(q.signature()));if(i==0)oldest=q.signature();recent.put(q.signature(),i);}assertEquals(oldest,QuantityAsFraction.next(pinned,limits,recent).signature());
 }
}
